// Sprite atlases (generated by tools/sprites) and the state -> animation frame mapping.

import { ATTACKS } from '../../shared/data/attacks';
import { phaseOf } from '../../shared/sim/combat';
import type { ViewEnt } from '../../shared/sim/snapshot';
import { F_RISING } from '../../shared/sim/snapshot';

export interface AtlasAnim { frames: { i: number; t: number; ph?: string }[]; loop: boolean }
export interface Atlas { id: string; cell: [number, number]; anchor: [number, number]; cols: number; count: number; anims: Record<string, AtlasAnim>; head?: [number, number, number, number] }
export interface Sheet { atlas: Atlas; img: HTMLImageElement; flipped: HTMLCanvasElement; white: HTMLCanvasElement }

const sheets = new Map<string, Sheet>();

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error('failed to load ' + src)); i.src = src; });
}

/** Pre-mirrored copy (whole sheet flipped, so cell order is reversed per row) and a white silhouette for hit flashes. */
function derive(img: HTMLImageElement, atlas: Atlas): { flipped: HTMLCanvasElement; white: HTMLCanvasElement } {
  const [cw, ch] = atlas.cell;
  const flipped = document.createElement('canvas'); flipped.width = img.width; flipped.height = img.height;
  const fc = flipped.getContext('2d')!;
  const rows = Math.ceil(atlas.count / atlas.cols);
  for (let i = 0; i < atlas.cols * rows; i++) {
    const sx = (i % atlas.cols) * cw, sy = Math.floor(i / atlas.cols) * ch;
    fc.save(); fc.translate(sx + cw, sy); fc.scale(-1, 1); fc.drawImage(img, sx, sy, cw, ch, 0, 0, cw, ch); fc.restore();
  }
  const white = document.createElement('canvas'); white.width = img.width; white.height = img.height;
  const wc = white.getContext('2d')!;
  wc.drawImage(img, 0, 0); wc.globalCompositeOperation = 'source-in'; wc.fillStyle = '#ffffff'; wc.fillRect(0, 0, img.width, img.height);
  return { flipped, white };
}

export async function loadSheets(base: string, onProgress?: (done: number, total: number) => void): Promise<void> {
  const index: Record<string, string> = await (await fetch(base + 'index.json')).json();
  const ids = Object.keys(index);
  let done = 0;
  await Promise.all(ids.map(async (id) => {
    const [atlas, img] = await Promise.all([fetch(base + index[id]).then((r) => r.json() as Promise<Atlas>), loadImage(base + id + '.png')]);
    sheets.set(id, { atlas, img, ...derive(img, atlas) });
    onProgress?.(++done, ids.length);
  }));
}

export function getSheet(id: string): Sheet | undefined { return sheets.get(id); }

/** Opaque bounds of the named animations, unioned over their frames: `[x, y, w, h]` inside
 *  the cell. Measured once per sheet, straight from the pixels, so UI that frames a sprite
 *  can centre and baseline it without clipping hair or a raised arm. */
const contentBoxes = new Map<string, [number, number, number, number]>();
export function contentBox(sheet: Sheet, anims: string[]): [number, number, number, number] {
  const key = `${sheet.atlas.id}:${anims.join(',')}`;
  const memo = contentBoxes.get(key);
  if (memo) return memo;
  const [cw, ch] = sheet.atlas.cell;
  const cv = document.createElement('canvas');
  cv.width = sheet.img.width; cv.height = sheet.img.height;
  const c = cv.getContext('2d', { willReadFrequently: true })!;
  c.drawImage(sheet.img, 0, 0);
  let x0 = cw, y0 = ch, x1 = -1, y1 = -1;
  for (const name of anims) {
    for (const f of sheet.atlas.anims[name]?.frames ?? []) {
      const ox = (f.i % sheet.atlas.cols) * cw, oy = Math.floor(f.i / sheet.atlas.cols) * ch;
      const px = c.getImageData(ox, oy, cw, ch).data;
      for (let y = 0; y < ch; y++) for (let x = 0; x < cw; x++) {
        if (px[(y * cw + x) * 4 + 3] <= 24) continue;
        if (x < x0) x0 = x;
        if (x > x1) x1 = x;
        if (y < y0) y0 = y;
        if (y > y1) y1 = y;
      }
    }
  }
  const box: [number, number, number, number] = x1 < 0 ? [0, 0, cw, ch] : [x0, y0, x1 - x0 + 1, y1 - y0 + 1];
  contentBoxes.set(key, box);
  return box;
}

/** Animation name for an entity's current state. */
export function animFor(e: ViewEnt): string {
  switch (e.st) {
    case 'idle': return 'idle';
    case 'walk': return 'walk';
    case 'run': return 'run';
    case 'jump': return e.flags & F_RISING ? 'jump' : 'fall';
    case 'attack': case 'grabatk': case 'throw': return e.atk ? ATTACKS[e.atk]?.anim ?? 'light1' : 'light1';
    case 'hurt': return e.t % 20 < 10 && (e.def === 'sc' || e.def === 'bt') ? 'hurt' : 'hurt2';
    case 'knock': return 'knock';
    case 'down': return 'down';
    case 'getup': return 'getup';
    case 'block': return 'block';
    case 'dodge': return 'dodge';
    case 'grab': return 'grab';
    case 'hold': return 'hold';
    case 'held': return 'held';
    case 'thrown': return 'thrown';
    case 'eat': return 'eat';
    case 'pickup': return 'pickup';
    case 'dead': case 'out': return 'defeat';
    case 'dizzy': case 'tired': return 'dizzy';
    case 'victory': return 'victory';
    case 'taunt': return 'taunt';
    case 'shop': return 'idle';
    default: return 'idle';
  }
}

function pickTimed(frames: AtlasAnim['frames'], t: number, loop: boolean): number {
  const total = frames.reduce((s, f) => s + f.t, 0) || 1;
  let tt = loop ? t % total : Math.min(t, total - 1);
  for (const f of frames) { if (tt < f.t) return f.i; tt -= f.t; }
  return frames[frames.length - 1].i;
}

/** Frame index inside the sheet. Attack animations follow the simulation's attack phases. */
export function frameFor(sheet: Sheet, e: ViewEnt): number {
  const name = animFor(e);
  const anim = sheet.atlas.anims[name] ?? sheet.atlas.anims.idle;
  if ((e.st === 'attack' || e.st === 'grabatk' || e.st === 'throw') && e.atk && ATTACKS[e.atk] && anim.frames.some((f) => f.ph)) {
    const a = ATTACKS[e.atk];
    let ph = phaseOf(a, e.t);
    if (ph === 'tele') ph = 's';
    if (ph === 'end') ph = 'r';
    const tele = a.telegraph ?? 0;
    const start = ph === 's' ? 0 : ph === 'a' ? tele + a.startup : tele + a.startup + a.active;
    const len = ph === 's' ? tele + a.startup : ph === 'a' ? a.active : a.recovery;
    const fr = anim.frames.filter((f) => f.ph === ph);
    if (!fr.length) return anim.frames[0].i;
    const local = e.t - start;
    const sum = fr.reduce((s, f) => s + f.t, 0);
    if (len >= sum * 1.5) return pickTimed(fr, local, true);
    const k = Math.min(fr.length - 1, Math.floor((local / Math.max(1, len)) * fr.length));
    return fr[Math.max(0, k)].i;
  }
  return pickTimed(anim.frames, e.t, anim.loop);
}
